<script setup>
import { computed } from 'vue'; const props = defineProps({ modelValue: String, label: String, placeholder: String, error: String, helper: String, required: Boolean, disabled: Boolean, rows: { type: Number, default: 3 }, id: String }); const emit = defineEmits(['update:modelValue']); const textareaId = computed(() => props.id || `textarea-${Math.random().toString(36).slice(2)}`);
</script>
<template><div><label v-if="label" :for="textareaId" class="mb-1.5 block text-sm font-medium text-[#172033]">{{ label }} <span v-if="required" class="text-red-500">*</span></label><textarea :id="textareaId" :value="modelValue" :rows="rows" :disabled="disabled" :placeholder="placeholder" :class="['ui-field h-auto resize-y px-3 py-2 leading-5', error && 'ui-field--error']" @input="emit('update:modelValue', $event.target.value)" /><p v-if="error" class="mt-1 text-xs text-[#DC2626]">{{ error }}</p><p v-else-if="helper" class="mt-1 text-xs text-[#667085]">{{ helper }}</p></div></template>
